// Count the encoder's clicks: CLK falls, then DT says which way.
const int CLK_PIN = 2;
const int DT_PIN = 3;
const int SW_PIN = 4;
int count = 0;
int lastClk = HIGH;

void setup() {
  Serial.begin(9600);
  pinMode(CLK_PIN, INPUT);
  pinMode(DT_PIN, INPUT);
  pinMode(SW_PIN, INPUT);
}

void loop() {
  int clk = digitalRead(CLK_PIN);
  if (lastClk == HIGH && clk == LOW) {
    if (digitalRead(DT_PIN) == HIGH) {
      count = count + 1;
    } else {
      count = count - 1;
    }
    Serial.println(count);
  }
  lastClk = clk;
  if (digitalRead(SW_PIN) == LOW && count != 0) {
    count = 0;
    Serial.println(count);
  }
  delay(1);
}
